public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null || start.length != 2 || end.length != 2 || paths.length == 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX < 0 || startX >= n || startY < 0 || startY >= n || endX < 0 || endX >= n || endY < 0 || endY >= n) {
        throw new IllegalArgumentException("Coordinates out of bounds");
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == endX && y == endY) {
            return "can be travelled";
        }

        visited[x][y] = true;

        for (int[] path : paths) {
            int nextX = x + path[0];
            int nextY = y + path[1];

            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY]) {
                queue.offer(new int[]{nextX, nextY});
            }
        }
    }

    return "cannot be travelled";
}

