public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1; // Return -1 if input is not positive
    }

    // Convert the integer to a character array
    char[] digits = String.valueOf(n).toCharArray();

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Find the first digit that is not in its correct position
    for (int i = 0; i < digits.length - 1; i++) {
        if (digits[i] > digits[i + 1]) {
            // Swap the digits
            char temp = digits[i];
            digits[i] = digits[i + 1];
            digits[i + 1] = temp;

            // Sort the remaining digits in ascending order
            Arrays.sort(digits, i + 1, digits.length);

            // Convert the character array back to an integer
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such digit is found, return -1
    return -1;
}

